#pragma once
// Build identity of this binary (server_bin, client_bin, kn_brain): the git describe / commit it
// was built from, when, and the network protocol it speaks. Generated by cmake/kn_version.cmake
// into kn_version.h at every build; shared/src/build_info.c is the only file that includes it
// (library kn_build_info), so a new commit relinks instead of recompiling everything.
// Wire fields (server-info query, finder heartbeat, coordinator hello, lobby meta): doc/backend.md
// "Build version".
#include <stdint.h>
#include <stddef.h>

// The product name players see (window titles, banners, --version, the launcher). The project
// was called KrunkNative: identifiers (repo, KRUNKNATIVE_* variables, kn_* targets, file and
// package names, user agents, protocol strings) keep that name.
#define KN_PRODUCT_NAME "Krunker Box Office"

typedef struct {
    const char *describe;     // "v1.0.0-51-g6f0cea9", "6f0cea9-dirty", "unknown"
    const char *commit;       // 12 hex digits, "" unknown
    int64_t commit_time;      // committer date of commit, unix seconds (0 unknown)
    int dirty;                // built from a tree with local changes
    const char *build_time;   // ISO-8601 UTC, "2026-10-12T05:00:00Z"
    int protocol_major;       // NET_PROTOCOL_MAJOR.MINOR (shared.h)
    int protocol_minor;
} KnBuildInfo;

const KnBuildInfo *kn_build_info(void);
// "v1.0.0-51-g6f0cea9 (6f0cea9e1234, built 2026-10-12T05:00:00Z, protocol 1.3)"
const char *kn_build_string(void);
// "1.3"
const char *kn_build_protocol(void);
